{% set pending_tasks = [] %}
{% set done_tasks = [] %}
{% set remarks_tasks = [] %}
{% set counts = namespace(pending=0, done=0, remarks=0) %}
{% for row in doc.items %}
	{% if row.status == "Done" %}
		{{ done_tasks.append(row) or "" }}
		{% set counts.done = counts.done + 1 %}
	{% else %}
		{{ pending_tasks.append(row) or "" }}
		{% set counts.pending = counts.pending + 1 %}
	{% endif %}
	{% if row.remarks %}
		{{ remarks_tasks.append(row) or "" }}
		{% set counts.remarks = counts.remarks + 1 %}
	{% endif %}
{% endfor %}

<style>
	.print-format {
		padding: 0 !important;
		font-family: Inter, Arial, sans-serif;
		color: #18212b;
		background: linear-gradient(180deg, #3b4449 50%, #f19f21 50%);
	}
	.print-format * {
		box-sizing: border-box;
	}
	.print-format .ceo-audit-page {
		padding: 18px 6px 30px;
	}
	.print-format .ceo-audit-hero {
		background: linear-gradient(135deg, #f19f21 0%, #3b4449 100%);
		color: #fff;
		padding: 28px 30px;
		border-radius: 20px;
		box-shadow: 0 18px 40px rgba(16, 58, 77, 0.18);
		margin-bottom: 20px;
	}
	.print-format .ceo-audit-eyebrow {
		font-size: 12px;
		letter-spacing: 0.16em;
		text-transform: uppercase;
		opacity: 0.75;
		margin-bottom: 10px;
	}
	.print-format .ceo-audit-hero h2 {
		margin: 0 0 8px;
		font-size: 30px;
		font-weight: 700;
		color: #fff;
	}
	.print-format .ceo-audit-hero p {
		margin: 0;
		max-width: 760px;
		font-size: 15px;
		opacity: 0.9;
	}
	.print-format .ceo-filter-bar {
		display: grid;
		grid-template-columns: repeat(3, minmax(0, 1fr));
		gap: 14px;
		margin-bottom: 18px;
		padding: 16px;
		border-radius: 18px;
		background: rgba(255, 255, 255, 0.9);
		border: 1px solid rgba(148, 163, 184, 0.18);
		box-shadow: 0 10px 24px rgba(15, 23, 42, 0.05);
	}
	.print-format .ceo-filter-field {
		padding: 10px 12px;
		border-radius: 14px;
		background: #f8fafc;
		border: 1px solid rgba(148, 163, 184, 0.18);
	}
	.print-format .ceo-filter-label {
		font-size: 13px;
		font-weight: 700;
		color: #334155;
		margin-bottom: 6px;
	}
	.print-format .ceo-filter-value {
		font-size: 15px;
		color: #0f172a;
	}
	.print-format .ceo-audit-summary {
		display: grid;
		grid-template-columns: repeat(4, minmax(0, 1fr));
		gap: 14px;
		margin-bottom: 18px;
	}
	.print-format .ceo-summary-card {
		padding: 18px 20px;
		border-radius: 18px;
		background: #fff;
		box-shadow: 0 12px 28px rgba(15, 23, 42, 0.07);
		border: 1px solid rgba(148, 163, 184, 0.18);
	}
	.print-format .ceo-summary-label {
		font-size: 13px;
		color: #5b6472;
		margin-bottom: 8px;
	}
	.print-format .ceo-summary-value {
		font-size: 34px;
		font-weight: 700;
		line-height: 1;
		color: #12212c;
	}
	.print-format .ceo-pending .ceo-summary-value {
		color: #b45309;
	}
	.print-format .ceo-done .ceo-summary-value {
		color: #047857;
	}
	.print-format .ceo-remarks .ceo-summary-value {
		color: #7c3aed;
	}
	.print-format .ceo-department-card {
		background: rgba(255, 255, 255, 0.94);
		border: 1px solid rgba(148, 163, 184, 0.18);
		border-radius: 22px;
		padding: 20px;
		box-shadow: 0 14px 36px rgba(15, 23, 42, 0.07);
	}
	.print-format .ceo-department-header {
		display: flex;
		justify-content: space-between;
		align-items: flex-start;
		gap: 16px;
		margin-bottom: 16px;
	}
	.print-format .ceo-department-header h3 {
		margin: 0 0 6px;
		font-size: 24px;
		color: #0f172a;
	}
	.print-format .ceo-department-meta {
		font-size: 13px;
		color: #52606d;
	}
	.print-format .ceo-count-pills {
		display: flex;
		flex-wrap: wrap;
		gap: 8px;
	}
	.print-format .ceo-pill {
		padding: 7px 12px;
		border-radius: 999px;
		font-size: 12px;
		font-weight: 600;
	}
	.print-format .ceo-pill-pending {
		background: #fff3c4;
		color: #8a5a00;
	}
	.print-format .ceo-pill-done {
		background: #d8f7e6;
		color: #0b6b46;
	}
	.print-format .ceo-pill-remarks {
		background: #efe4ff;
		color: #6d28d9;
	}
	.print-format .ceo-columns {
		display: grid;
		grid-template-columns: repeat(3, minmax(0, 1fr));
		gap: 14px;
	}
	.print-format .ceo-column {
		border-radius: 18px;
		padding: 14px;
		min-height: 100%;
	}
	.print-format .ceo-column-pending {
		background: #fff9e8;
	}
	.print-format .ceo-column-done {
		background: #eefcf5;
	}
	.print-format .ceo-column-remarks {
		background: #f7f2ff;
	}
	.print-format .ceo-column-title {
		font-size: 16px;
		font-weight: 700;
		margin-bottom: 12px;
		color: #17212b;
	}
	.print-format .ceo-column-body {
		display: grid;
		gap: 10px;
	}
	.print-format .ceo-task-row {
		background: rgba(255, 255, 255, 0.8);
		border-radius: 14px;
		padding: 12px;
		border: 1px solid rgba(255, 255, 255, 0.7);
		page-break-inside: avoid;
	}
	.print-format .ceo-task-area {
		font-size: 12px;
		font-weight: 700;
		letter-spacing: 0.04em;
		text-transform: uppercase;
		color: #52606d;
		margin-bottom: 5px;
	}
	.print-format .ceo-task-text {
		font-size: 15px;
		line-height: 1.5;
		color: #18212b;
		white-space: pre-wrap;
	}
	.print-format .ceo-task-followup,
	.print-format .ceo-task-remark {
		margin-top: 8px;
		font-size: 13px;
		line-height: 1.5;
		color: #4a5565;
		white-space: pre-wrap;
	}
	.print-format .ceo-task-empty {
		padding: 20px;
		border-radius: 16px;
		background: rgba(255, 255, 255, 0.9);
		color: #5b6472;
		font-size: 15px;
	}
	@media print {
		.print-format {
			background: #fff !important;
		}
	}
</style>

<div class="ceo-audit-page">
	<div class="ceo-audit-hero">
		<div class="ceo-audit-eyebrow">Executive Daily Checklist View</div>
		<h2>Department Performance at a Glance</h2>
		<p>Reveiw Daily, Weekly and Monthly Completed and Pending Tasks Across all Departments.</p>
	</div>

	<div class="ceo-filter-bar">
		<div class="ceo-filter-field">
			<div class="ceo-filter-label">Date</div>
			<div class="ceo-filter-value">{{ doc.get_formatted("date") }}</div>
		</div>
		<div class="ceo-filter-field">
			<div class="ceo-filter-label">Frequency</div>
			<div class="ceo-filter-value">{{ doc.frequency or "" }}</div>
		</div>
		<div class="ceo-filter-field">
			<div class="ceo-filter-label">Department</div>
			<div class="ceo-filter-value">{{ doc.department or "" }}</div>
		</div>
	</div>

	<div class="ceo-audit-summary">
		<div class="ceo-summary-card ceo-neutral">
			<div class="ceo-summary-label">Departments</div>
			<div class="ceo-summary-value">1</div>
		</div>
		<div class="ceo-summary-card ceo-pending">
			<div class="ceo-summary-label">Pending Tasks</div>
			<div class="ceo-summary-value">{{ counts.pending }}</div>
		</div>
		<div class="ceo-summary-card ceo-done">
			<div class="ceo-summary-label">Done Tasks</div>
			<div class="ceo-summary-value">{{ counts.done }}</div>
		</div>
		<div class="ceo-summary-card ceo-remarks">
			<div class="ceo-summary-label">Remarks</div>
			<div class="ceo-summary-value">{{ counts.remarks }}</div>
		</div>
	</div>

	<div class="ceo-department-card">
		<div class="ceo-department-header">
			<div>
				<h3>{{ doc.department or "Department" }}</h3>
				<div class="ceo-department-meta">Audit Reference: {{ doc.name }}</div>
			</div>
			<div class="ceo-count-pills">
				<span class="ceo-pill ceo-pill-pending">Pending {{ counts.pending }}</span>
				<span class="ceo-pill ceo-pill-done">Done {{ counts.done }}</span>
				<span class="ceo-pill ceo-pill-remarks">Remarks {{ counts.remarks }}</span>
			</div>
		</div>
		<div class="ceo-columns">
			<div class="ceo-column ceo-column-pending">
				<div class="ceo-column-title">Pending</div>
				<div class="ceo-column-body">
					{% if pending_tasks %}
						{% for task in pending_tasks %}
							<div class="ceo-task-row">
								<div class="ceo-task-area">{{ task.area or "General" }}</div>
								<div class="ceo-task-text">{{ task.task or "" }}</div>
								{% if task.follow_up %}<div class="ceo-task-followup">{{ task.follow_up }}</div>{% endif %}
							</div>
						{% endfor %}
					{% else %}
						<div class="ceo-task-empty">No pending tasks.</div>
					{% endif %}
				</div>
			</div>
			<div class="ceo-column ceo-column-done">
				<div class="ceo-column-title">Done</div>
				<div class="ceo-column-body">
					{% if done_tasks %}
						{% for task in done_tasks %}
							<div class="ceo-task-row">
								<div class="ceo-task-area">{{ task.area or "General" }}</div>
								<div class="ceo-task-text">{{ task.task or "" }}</div>
								{% if task.follow_up %}<div class="ceo-task-followup">{{ task.follow_up }}</div>{% endif %}
							</div>
						{% endfor %}
					{% else %}
						<div class="ceo-task-empty">No done tasks.</div>
					{% endif %}
				</div>
			</div>
			<div class="ceo-column ceo-column-remarks">
				<div class="ceo-column-title">Remarks</div>
				<div class="ceo-column-body">
					{% if remarks_tasks %}
						{% for task in remarks_tasks %}
							<div class="ceo-task-row">
								<div class="ceo-task-area">{{ task.area or "General" }}</div>
								<div class="ceo-task-text">{{ task.task or "" }}</div>
								<div class="ceo-task-remark">{{ task.remarks or "" }}</div>
							</div>
						{% endfor %}
					{% else %}
						<div class="ceo-task-empty">No remarks recorded.</div>
					{% endif %}
				</div>
			</div>
		</div>
	</div>
</div>
